// MathJax 4 with the math font of the presentation's font set (default: Bonum) (generated by MathJax from TeX Gyre Bonum Math;
// glyph outlines verified identical to the official texgyrebonum-math.otf v1.005, see tools/).
let ready = false, readyResolve;
export const mathReady = new Promise(r => { readyResolve = r; });
export const opts = { hunTrig: true, decComma: true, displayInline: true };

let activeFont = null;
export const activeMathFont = () => activeFont;
/** key: one of the MathJax 4 math fonts (bonum, pagella, termes, schola, modern, newcm, tex, stix2, fira, dejavu, asana). */
const LOCAL = () => new URL('mathjax/', document.baseURI).href;
const MJ_SRC = () => LOCAL() + 'startup.js';
function mjConfig(key, local, onReady) {
  return {
    loader: {
      load: ['input/tex', 'output/svg'],
      paths: { fonts: local + 'fonts' }
    },
    output: { font: 'mathjax-' + key, linebreaks: { inline: false } },
    svg: { fontCache: 'none' },   // Prezi: self-contained SVGs (exported into PowerPoint/PDF as pictures)
    tex: {
      macros: {
        tg: '\\operatorname{tg}', ctg: '\\operatorname{ctg}',
        arctg: '\\operatorname{arc\\,tg}', arcctg: '\\operatorname{arc\\,ctg}',
        sh: '\\operatorname{sh}', ch: '\\operatorname{ch}', th: '\\operatorname{th}', cth: '\\operatorname{cth}',
        R: '\\mathbb{R}', N: '\\mathbb{N}', Z: '\\mathbb{Z}', Q: '\\mathbb{Q}'
      }
    },
    startup: { typeset: false, ready: onReady }
  };
}
export function startMathJax(key = 'bonum') {
  activeFont = key;
  window.MathJax = mjConfig(key, LOCAL(), () => {
    window.MathJax.startup.defaultReady();
    window.MathJax.startup.promise.then(() => {
      try { document.head.appendChild(window.MathJax.svgStylesheet()); } catch (e) { /* optional */ }
      ready = true; readyResolve();
    });
  });
  const s = document.createElement('script');
  s.src = MJ_SRC(); s.async = true;
  document.head.appendChild(s);
}
/* Formulas next to a text in another math-capable font use that font's math letters. MathJax picks its math
   font at start-up, so every further font gets its own small MathJax document (same TeX settings, its own SVG
   output with that font), loaded the first time it is needed – in this same page, without blocking the others. */
const extra = new Map();     // font key -> Promise<{doc, out, queue}>
function docFor(key) {
  if (extra.has(key)) return extra.get(key);
  const p = mathReady.then(async () => {
    const MJ = window.MathJax, name = 'mathjax-' + key;
    MJ.config.loader.paths[name] = LOCAL() + `fonts/${name}-font`;
    if (!MJ._.output.fonts?.[name]) await MJ.loader.load(`[${name}]/svg`);
    const FontClass = Object.values(MJ._.output.fonts[name].svg_ts)[0];
    const out = new MJ._.output.svg_ts.SVG({fontData: FontClass, fontCache: 'none', linebreaks: {inline: false}, dynamicPrefix: `[${name}]/svg/dynamic`});
    const input = new MJ._.input.tex_ts.TeX({...MJ.config.tex});
    const doc = MJ._.mathjax.mathjax.document(document, {InputJax: input, OutputJax: out});
    return {doc, out, queue: Promise.resolve()};
  });
  extra.set(key, p); return p;
}
async function convertIn(key, tex, display, wrap) {
  const d = await docFor(key);
  const run = () => { d.out.options.linebreaks.inline = !!wrap && !display; return d.doc.convertPromise(tex, {display: !!display, em: 16, ex: 8, containerWidth: 1280}); };
  const r = d.queue.then(run, run); d.queue = r.catch(() => null); return r;
}
/** Text family (from a CSS font-family like "MP pagella") -> its math font, or null (= the presentation's). */
const MATH_OF = {bonum: 'bonum', pagella: 'pagella', termes: 'termes', schola: 'schola', lmodern: 'modern', newcm: 'newcm', stix2: 'stix2', fira: 'fira', dejavu: 'dejavu'};
export function mathFontFromCSS(css) { const m = String(css || '').match(/MP ([a-z0-9]+)/); return m ? (MATH_OF[m[1]] || null) : null; }
/** Font + boldness a formula takes from the text around it (walks up from the element). */
export function mathStyleOf(el, stop) {
  let font = null, bold = false;
  for (let e = el; e && e.nodeType === 1; e = e.parentElement) {
    if (font === null && e.style && e.style.fontFamily && /MP [a-z0-9]+/.test(e.style.fontFamily)) font = mathFontFromCSS(e.style.fontFamily) || '';
    if (!bold && (e.tagName === 'STRONG' || e.tagName === 'B' || (e.style && (e.style.fontWeight === 'bold' || +e.style.fontWeight >= 600)))) bold = true;
    if (e === stop) break;
  }
  return {font: font || null, bold};
}

export function isReady() { return ready; }

function hun(tex, display, bold) {
  let s = tex;
  if (opts.hunTrig) {
    s = s.replace(/\\arctan(?![a-zA-Z])/g, '\\arctg').replace(/\\arccot(?![a-zA-Z])/g, '\\arcctg')
      .replace(/\\tan(?![a-zA-Z])/g, '\\tg').replace(/\\cot(?![a-zA-Z])/g, '\\ctg');
  }
  if (opts.decComma) s = s.replace(/(\d),(?=\d)/g, '$1{,}');
  // inline formulas in display size (full fractions, limits above/below) – but they stay in the line
  if (bold) s = '\\boldsymbol{' + s + '}';
  if (!display && opts.displayInline) s = '\\displaystyle ' + s;
  return s;
}

const cache = new Map();   // key -> Promise<{html,error} | null>
const done = new Map();    // key -> finished result, used synchronously so re-created views never flicker
const keyOf = (tex, display, bold, wrap, font) => (display ? 'D' : 'I') + (bold ? 'B' : '') + (wrap ? 'W' : '') + (font && font !== activeFont ? '@' + font : '') + (opts.hunTrig ? 1 : 0) + (opts.decComma ? 1 : 0) + (opts.displayInline ? 1 : 0) + '|' + tex;
let queue = Promise.resolve();
/** wrap: the formula may break into lines (after =, +, −, relations…) at the edge of its text box. */
export function renderSVG(tex, display, bold, wrap, font) {
  const key = keyOf(tex, display, bold, wrap, font);
  if (cache.has(key)) return cache.get(key);
  // one formula at a time, so the line-break setting belongs to the right formula
  const other = font && font !== activeFont;
  const p = (other
    // another font: its own document and queue; if it cannot be loaded, the presentation's font is used
    ? convertIn(font, hun(tex, display, bold), display, wrap).catch(e => { console.warn('math font', font, e); return renderSVG(tex, display, bold, wrap, null); })
      .then(r => r && r.html !== undefined ? r : r)
    : (queue = queue.then(() => mathReady).then(() => {
        const lb = window.MathJax.startup.output?.options?.linebreaks; if (lb) lb.inline = !!wrap && !display;
        return window.MathJax.tex2svgPromise(hun(tex, display, bold), { display: !!display });
      }).catch(() => null)))
    .then(node => {
      if (node && node.html !== undefined) return node;      // came back already finished (fallback above)
      if (node.querySelector('[data-mjx-error], merror, [data-mml-node="merror"]')) return { html: node.outerHTML, error: true };
      return { html: node.outerHTML, error: false };
    })
    .catch(() => null)
    .then(r => { done.set(key, r); return r; });
  cache.set(key, p);
  if (cache.size > 3000) cache.delete(cache.keys().next().value);
  return p;
}
export function clearMathCache() { cache.clear(); done.clear(); }

/** Fill an element with the rendered formula (keeps the old picture until the new one is ready). */
export function renderInto(el, tex, display, onDone, bold, wrap, font) {
  const tok = el._mj = (el._mj || 0) + 1;
  if (!tex) { el.innerHTML = '<span class="mpending">∅</span>'; return; }
  const key = keyOf(tex, display, bold, wrap, font);
  if (done.has(key)) {
    const r = done.get(key);
    if (r) { if (el._html !== r.html) { el.innerHTML = r.html; el._html = r.html; } }
    else { el.innerHTML = ''; const c = document.createElement('span'); c.className = 'mpending merr'; c.textContent = tex; el.appendChild(c); el._html = null; }
    onDone && onDone();
    return;
  }
  if (!el.firstChild) { const c = document.createElement('span'); c.className = 'mpending'; c.textContent = tex; el.appendChild(c); }
  renderSVG(tex, display, bold, wrap, font).then(r => {
    if (el._mj !== tok) return;
    if (!r) { el.innerHTML = ''; const c = document.createElement('span'); c.className = 'mpending merr'; c.textContent = tex; el.appendChild(c); }
    else { el.innerHTML = r.html; el._html = r.html; }
    onDone && onDone();
  });
}
